SELECT DATE_TRUNC('MONTH', customers.signup_date) AS signup_month, CASE WHEN customers.country IN ('DE', 'US') THEN 'core' ELSE 'other' END AS country_group, COUNT(DISTINCT subscriptions.monthly_fee) AS unique_customers FROM subscriptions JOIN customers ON subscriptions.customer_id = customers.id WHERE subscriptions.customer_id IS NOT NULL GROUP BY DATE_TRUNC('MONTH', customers.signup_date), CASE WHEN customers.country IN ('DE', 'US') THEN 'core' ELSE 'other' END
